using System.Data;
using System.Globalization;
using System.Windows;
using System.Windows.Controls;
namespace Hisab;
public sealed partial class MainWindow
{
    void PurchasingPage()
    {
        Heading(T("المشتريات والاستلام","Purchasing & receiving"),T("طلب المورد ثم استلام البضاعة ثم الفاتورة، دون تكرار المخزون.","Supplier order, goods receipt, then invoice — stock is received once."));
        body.Children.Add(Actions(Btn(T("طلب شراء جديد","New purchase order"),()=>PurchaseOrderForm(),true),Btn(T("فوترة الاستلامات","Bill receipts"),BillReceiptsForm),Btn(T("تكاليف الشحن والشراء","Landed costs"),LandedCostForm),Btn(T("المخزون","Inventory"),()=>Navigate("inventory"))));
        var rows=S.Table("SELECT o.id,'PO-'||o.id number,a.name supplier,l.name location,o.expected,o.state FROM purchase_orders o JOIN accounts a ON a.id=o.supplier JOIN locations l ON l.id=o.location ORDER BY o.id DESC");
        var grid=Grid(rows,("number",T("الطلب","Order"),1),("supplier",T("المورد","Supplier"),2),("location",T("الموقع","Location"),1.5),("expected",T("التاريخ المتوقع","Expected date"),1.2),("state",T("الحالة","State"),1));body.Children.Add(grid);
        body.Children.Add(Actions(Btn(T("تفاصيل واستلام","Details & receive"),()=>PurchaseOrderDetails(Selected(grid))),Btn(T("اعتماد الطلب","Issue order"),()=>{A.IssuePurchaseOrder(Selected(grid));Navigate("purchasing");}),Btn(T("إلغاء المتبقي","Cancel outstanding"),()=>{if(Confirm(T("إلغاء الجزء غير المستلم؟ تبقى الاستلامات المسجلة.","Cancel the unreceived remainder? Posted receipts stay recorded."))){A.CancelPurchaseOrder(Selected(grid));Navigate("purchasing");}})));
        body.Children.Add(Text(T("استلامات البضاعة","Goods receipts"),22,true));var receipts=Grid(S.Table("SELECT d.id,d.number,d.date,a.name supplier,d.reversed FROM documents d JOIN accounts a ON a.id=d.party WHERE d.kind='GR' ORDER BY d.id DESC"),("number",T("المستند","Document"),1),("date",T("التاريخ","Date"),1),("supplier",T("المورد","Supplier"),2),("reversed",T("ملغى 1","Cancelled 1"),1));body.Children.Add(receipts);body.Children.Add(Actions(Btn(T("فتح المستند","Open document"),()=>ShowDocument(Selected(receipts))),Btn(T("إرجاع غير المفوتر","Return unbilled goods"),()=>ReturnForm(Selected(receipts)))));
    }
    void PurchaseOrderForm(long? selectedItem=null,long location=1,decimal quantity=1)
    {
        var (w,p,finish)=Dialog(T("طلب شراء جديد","New purchase order"),900);var supplier=Choose(UiAccounts().Where(a=>a.Kind=="Supplier"));p.Children.Add(Field(T("المورد","Supplier"),supplier));var loc=LocationPicker(p);loc.SelectedItem=loc.Items.Cast<StockLocation>().FirstOrDefault(l=>l.Id==location);var expected=new DatePicker{SelectedDate=DateTime.Today};p.Children.Add(Field(T("موعد الوصول المتوقع","Expected arrival"),expected));var item=Choose(UiItems().Where(i=>i.Stock));item.SelectedItem=item.Items.Cast<Item>().FirstOrDefault(i=>i.Id==selectedItem);BarcodeInput(p,item);p.Children.Add(Field(T("الصنف","Item"),item));var qty=Input(quantity.ToString(CultureInfo.InvariantCulture),true);var price=Input("0",true);p.Children.Add(Field(T("الكمية","Quantity"),qty));p.Children.Add(Field(T("تكلفة الوحدة قبل الضريبة JOD","Unit cost before tax JOD"),price));var lines=new List<PurchaseOrderLine>();var list=new ListBox{MaxHeight=200};
        void Refresh(){list.ItemsSource=lines.Select(l=>S.LocalName("items",l.Item,vm.Arabic)+" · "+l.Quantity+" × "+l.UnitCost+" JOD").ToList();}
        p.Children.Add(Actions(Btn(T("إضافة السطر","Add line"),()=>{var l=new PurchaseOrderLine(GetItem(item).Id,Store.Parse(qty.Text),Store.Parse(price.Text));if(l.Quantity<=0||l.UnitCost<=0)throw new InvalidOperationException(T("الكمية والتكلفة موجبتان","Quantity and cost must be positive"));lines.Add(l);Refresh();}),Btn(T("إزالة السطر","Remove line"),()=>{if(list.SelectedIndex>=0){lines.RemoveAt(list.SelectedIndex);Refresh();}})));p.Children.Add(list);p.Children.Add(Btn(T("حفظ مسودة الطلب","Save draft order"),()=>{if(!Confirm(string.Join("\n",list.Items.Cast<string>())))return;A.CreatePurchaseOrder(GetAccount(supplier).Id,PickLocation(loc),GetDate(expected),lines);finish();Navigate("purchasing");},true));w.ShowDialog();
    }
    void PurchaseOrderDetails(long order)
    {
        var (w,p,finish)=Dialog(T("طلب شراء ","Purchase order ")+order,950);var rows=S.Table("SELECT l.*,i.name FROM purchase_order_lines l JOIN items i ON i.id=l.item WHERE order_id=@p0",order);var controls=new List<(long Line,TextBox Qty,TextBox Serials)>();
        foreach(DataRow r in rows.Rows){long id=(long)r["id"],item=(long)r["item"],received=A.ReceivedQuantity(id);p.Children.Add(Text(S.LocalName("items",item,vm.Arabic)+T(" — طلب / استلام: "," — ordered / received: ")+Store.D((long)r["qty"])+" / "+Store.D(received),20,true));var qty=Input("0",true);p.Children.Add(Field(T("الكمية المستلمة الآن","Quantity received now"),qty));var serials=S.IsSerialized(item)?SerialInput(p):Input();controls.Add((id,qty,serials));p.Children.Add(Btn(T("تعديل كمية وتكلفة الطلب","Amend order quantity & cost"),()=>{finish();AmendOrderLineForm(id);}));}
        var date=Date();p.Children.Add(Field(T("تاريخ الاستلام","Receipt date"),date));p.Children.Add(Btn(T("مراجعة واستلام البضاعة","Review & receive goods"),()=>{var lines=controls.Select(x=>new ReceiptInput(x.Line,Store.Parse(x.Qty.Text),x.Serials.Text)).Where(x=>x.Quantity!=0).ToList();if(Confirm(string.Join("\n",lines.Select(l=>"#"+l.OrderLine+": "+l.Quantity)))){long id=A.ReceivePurchaseOrder(order,GetDate(date),lines);finish();Navigate("purchasing");ShowDocument(id);}},true));w.ShowDialog();
    }
    void AmendOrderLineForm(long id)
    {
        var r=S.Table("SELECT l.*,o.expected FROM purchase_order_lines l JOIN purchase_orders o ON o.id=l.order_id WHERE l.id=@p0",id).Rows[0];var (w,p,finish)=Dialog(T("تعديل طلب الشراء","Amend purchase order"));var qty=Input(Store.D((long)r["qty"]).ToString(CultureInfo.InvariantCulture),true);var cost=Input(Store.D((long)r["price"]).ToString(CultureInfo.InvariantCulture),true);var expected=new DatePicker{SelectedDate=DateTime.Parse((string)r["expected"])};var reason=Input();p.Children.Add(Field(T("إجمالي الكمية المطلوبة","Total ordered quantity"),qty));p.Children.Add(Field(T("تكلفة الوحدة للاستلامات القادمة","Unit cost for future receipts"),cost));p.Children.Add(Field(T("التاريخ المتوقع","Expected date"),expected));p.Children.Add(Field(T("سبب التعديل","Amendment reason"),reason));p.Children.Add(Btn(T("حفظ التعديل","Save amendment"),()=>{A.AmendPurchaseOrderLine(id,Store.Parse(qty.Text),Store.Parse(cost.Text),GetDate(expected),reason.Text);finish();Navigate("purchasing");},true));w.ShowDialog();
    }
    List<PositionChoice> ReceiptChoices(long? supplier=null,bool unbilled=false)
    {
        var rows=S.Table("SELECT l.id,l.description,l.qty,d.number FROM invoice_lines l JOIN documents d ON d.id=l.doc JOIN items i ON i.id=l.item WHERE d.kind IN ('GR','PI') AND d.reversed=0 AND i.stock=1 AND (@p0 IS NULL OR d.party=@p0) AND NOT EXISTS(SELECT 1 FROM receipt_bills b WHERE b.line=l.id) AND (@p1=0 OR d.kind='GR') ORDER BY d.id DESC",supplier,unbilled?1:0);return rows.Rows.Cast<DataRow>().Where(r=>!unbilled||A.UnbilledQuantity((long)r["id"])>0).Select(r=>new PositionChoice((long)r["id"],r["number"]+" · "+r["description"]+" · "+Store.D(unbilled?A.UnbilledQuantity((long)r["id"]):(long)r["qty"]))).ToList();
    }
    void BillReceiptsForm()
    {
        var (w,p,finish)=Dialog(T("فاتورة استلامات المورد","Invoice supplier receipts"),950);var supplier=Choose(UiAccounts().Where(a=>a.Kind=="Supplier"));p.Children.Add(Field(T("المورد","Supplier"),supplier));var receipt=Choose(Array.Empty<PositionChoice>());p.Children.Add(Field(T("سطر الاستلام — الكمية المتبقية","Receipt line — remaining quantity"),receipt));var lines=new List<BillInput>();var list=new ListBox{MaxHeight=200};supplier.SelectionChanged+=(s,e)=>{receipt.ItemsSource=ReceiptChoices((supplier.SelectedItem as Account)?.Id,true);lines.Clear();list.ItemsSource=null;};var qty=Input("1",true);var price=Input("0",true);p.Children.Add(Field(T("الكمية المفوترة الآن","Quantity billed now"),qty));p.Children.Add(Field(T("سعر الوحدة قبل الضريبة JOD","Invoice unit price before tax JOD"),price));receipt.SelectionChanged+=(s,e)=>{if(receipt.SelectedItem is PositionChoice c&&c.Id!=null)price.Text=Store.D(Convert.ToInt64(S.Scalar("SELECT price FROM invoice_lines WHERE id=@p0",c.Id))).ToString(CultureInfo.InvariantCulture);};
        void Refresh(){list.ItemsSource=lines.Select(l=>"#"+l.ReceiptLine+" · "+l.Quantity+" × "+l.UnitCost).ToList();}
        p.Children.Add(Actions(Btn(T("إضافة سطر","Add line"),()=>{long id=(receipt.SelectedItem as PositionChoice)?.Id??throw new InvalidOperationException(T("اختر الاستلام","Choose receipt"));if(lines.Any(l=>l.ReceiptLine==id))throw new InvalidOperationException(T("السطر مضاف بالفعل","Line already added"));lines.Add(new(id,Store.Parse(qty.Text),Store.Parse(price.Text)));Refresh();}),Btn(T("إزالة المحدد","Remove selected"),()=>{if(list.SelectedIndex>=0){lines.RemoveAt(list.SelectedIndex);Refresh();}})));p.Children.Add(list);var date=Date();var vat=Input(S.Setting("vat","16"),true);p.Children.Add(Field(T("تاريخ الفاتورة","Invoice date"),date));p.Children.Add(Field(T("نسبة الضريبة %","Tax rate %"),vat));p.Children.Add(Text(T("تسجل الفاتورة التزام المورد؛ لا تستلم المخزون مرة ثانية. سجّل الدفع من سند الصرف.","This invoice records the supplier payable without receiving stock again. Record payment using Pay money."),17));p.Children.Add(Btn(T("مراجعة وحفظ الفاتورة","Review & save invoice"),()=>{if(Confirm(string.Join("\n",list.Items.Cast<string>()))){long id=A.BillReceipts(GetAccount(supplier).Id,GetDate(date),lines,Store.Parse(vat.Text));finish();Navigate("purchasing");ShowDocument(id);}},true));w.ShowDialog();
    }
    void LandedCostForm()
    {
        var (w,p,finish)=Dialog(T("تكاليف الشحن والشراء","Landed costs"),1000);var supplier=Choose(UiAccounts().Where(a=>a.Kind=="Supplier"));p.Children.Add(Field(T("مورد التكلفة / شركة الشحن","Charge supplier / freight company"),supplier));var cash=Choose(UiAccounts().Where(a=>a.Kind=="Cash"));p.Children.Add(Field(T("حساب الدفع — اتركه فارغًا للآجل","Payment account — leave blank for payable"),cash));var amount=Input("0",true);p.Children.Add(Field(T("التكلفة القابلة للرسملة دون ضريبة قابلة للاسترداد JOD","Capitalizable cost excluding recoverable tax JOD"),amount));var date=Date();p.Children.Add(Field(T("تاريخ التكلفة","Charge date"),date));var source=Choose(S.Table("SELECT d.id,d.number FROM documents d WHERE d.reversed=0 AND d.kind IN ('PV','JV') AND EXISTS(SELECT 1 FROM entries e JOIN accounts a ON a.id=e.account WHERE e.doc=d.id AND a.code='2196' AND e.debit>0)").Rows.Cast<DataRow>().Select(r=>new PositionChoice((long)r["id"],(string)r["number"])));p.Children.Add(Field(T("تكلفة مسجلة سابقًا بحساب تسوية الشراء — اختياري","Previously recorded acquisition-clearing charge — optional"),source));
        var receipts=new ListBox{ItemsSource=ReceiptChoices(),SelectionMode=SelectionMode.Multiple,MaxHeight=200};p.Children.Add(Field(T("حدد أسطر الاستلام","Select receipt lines"),receipts));var method=Choose(new[]{new Choice("value",T("حسب القيمة","By value")),new Choice("quantity",T("حسب الكمية","By quantity")),new Choice("manual",T("يدوي","Manual"))});method.DisplayMemberPath="Label";method.SelectedIndex=0;p.Children.Add(Field(T("طريقة التوزيع","Allocation method"),method));var manual=Input();manual.AcceptsReturn=true;manual.MinHeight=75;p.Children.Add(Field(T("يدوي: مبلغ لكل سطر محدد بترتيب القائمة، مبلغ في كل سطر","Manual: amount per selected line in list order, one per line"),manual));var reason=Input();p.Children.Add(Field(T("البيان","Description"),reason));var preview=Text("",18);p.Children.Add(preview);
        IReadOnlyList<CostAllocation> Allocation(){var selected=receipts.Items.Cast<PositionChoice>().Where(c=>receipts.SelectedItems.Contains(c)).Select(c=>c.Id!.Value).ToArray();if((method.SelectedItem as Choice)?.Key!="manual")return A.AllocateLandedCost(Store.Parse(amount.Text),selected,(method.SelectedItem as Choice)?.Key=="quantity");var values=manual.Text.Split(new[]{'\n','\r'},StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries);if(values.Length!=selected.Length)throw new InvalidOperationException(T("أدخل مبلغًا لكل سطر محدد","Enter one amount per selected line"));return selected.Select((id,i)=>new CostAllocation(id,Store.Parse(values[i]))).ToArray();}
        p.Children.Add(Actions(Btn(T("معاينة التوزيع","Preview allocation"),()=>preview.Text=string.Join("\n",Allocation().Select(a=>"#"+a.ReceiptLine+": "+a.Amount+" JOD"))),Btn(T("مراجعة وترحيل","Review & post"),()=>{var allocations=Allocation();if(Confirm(string.Join("\n",allocations.Select(a=>"#"+a.ReceiptLine+": "+a.Amount+" JOD")))){A.AddLandedCost(GetDate(date),GetAccount(supplier).Id,(cash.SelectedItem as Account)?.Id,Store.Parse(amount.Text),allocations,reason.Text,(source.SelectedItem as PositionChoice)?.Id);finish();Navigate("purchasing");}},true)));w.ShowDialog();
    }
